"use strict";(self.webpackChunkudonarium=self.webpackChunkudonarium||[]).push([[9556],{36099(e){e.exports=JSON.parse('{"ko_kr":{"Irisbane":{"zero_dice_count":"\ud310\uc815 \uc218\uac00 0\uc785\ub2c8\ub2e4","success_dice_count":"\uc131\uacf5 \uc8fc\uc0ac\uc704 \uc218 %{count}","attack_power":"\xd7 \uacf5\uaca9\ub825 %{power}","damage":"\ub300\ubbf8\uc9c0 %{damage}","damage_with_mod":"\ub300\ubbf8\uc9c0 %{damage}%{operator}%{mod_value}","SceneSituation":{"name":"\uc2dc\ucd94\uc5d0\uc774\uc158","d66_sort_type":"NO_SORT","items":[["1..3",["\u3010\uc77c\uc0c1\u3011\uc544\ubb34\uac83\ub3c4 \ubcc0\ud558\uc9c0 \uc54a\ub294 \uc77c\uc0c1\uc758 \ud55c \uc7a5\uba74. \ubcc0\ud654\ud558\uae30 \uc26c\uc6b4 \uc138\uacc4\uc5d0\uc11c\ub294 \uadf8\uac83\uc774 \ub9e4\uc6b0 \uc18c\uc911\ud558\ub2e4.","\u3010\uc900\ube44\u3011\ubb34\uc5b8\uac00\ub97c \ud558\uae30 \uc704\ud55c \ucc44\ube44\ub97c \ud558\ub294 \ud55c \uc7a5\uba74. \uc815\ubcf4 \uc218\uc9d1, \uc1fc\ud551 \uc6d0\uc815, \ud574\uc57c \ud560 \uc77c\uc740 \uac00\ub4dd\ud558\ub2e4.","\u3010\ucde8\ubbf8\u3011\uc790\uc2e0\uc758 \uc2dc\uac04\uc744 \uc720\ud6a8\ud558\uac8c \ud65c\uc6a9\ud558\ub294 \ud55c \uc7a5\uba74. \ucad3\uae30\uc9c0 \uc54a\ub294 \ub9cc\ud07c \ub9c8\uc74c\uc774 \uac00\ubccd\uace0 \uc0c1\ucf8c\ud558\ub2e4.","\u3010\uce74\ud398\u3011\ud55c\uc228 \ub3cc\ub9ac\uba70 \uae30\ud638\ud488\uc744 \uc990\uae30\ub294 \ud55c \uc7a5\uba74. \uc628\ud654\ud55c \uacf5\uae30\ub294 \uadf8\ub7ec\ub098 \uc655\uc655 \ubcc0\ud558\uae30 \uc27d\ub2e4.","\u3010\ub2e8\ub828\u3011\ubab8\uc744 \ub2e8\ub828\ud558\uace0 \ub9c8\uc74c\uc744 \uae30\ub974\ub294 \uc218\ub828\uc758 \ud55c \uc7a5\uba74. \uc790\uc2e0\ub9cc \uad1c\ucc2e\ub2e4\uba74 \uadf8 \ubc29\ubc95\ub3c4 \ubb34\uc5c7\uc774\ub4e0 \uc88b\ub2e4.","\u3010\uc9c1\ubb34\u3011\uc5ed\ud560\uc5d0 \ub530\ub77c \uc77c\uc5d0 \ud798\uc4f0\ub294 \ud55c \uc7a5\uba74. \ubaa9\uc801\uc774 \ubb34\uc5c7\uc774\ub4e0 \ud574\uc57c \ud560 \uc77c\uc5d0\ub294 \ubcc0\ud568\uc774 \uc5c6\ub2e4."]],["4..6",["\u3010\uc774\ub3d9\u3011\uc5b4\ub518\uac00\uc5d0\uc11c \uc5b4\ub518\uac00\ub85c \ud5a5\ud558\ub294 \ud55c \uc7a5\uba74. \ub098\uc544\uac00\uace0 \uc788\ub2e4\uba74 \uc218\ub2e8\ub3c4 \ubaa9\uc801\uc9c0\ub3c4 \uc0c1\uad00\uc5c6\ub2e4.","\u3010\ubb18\uc804\u3011\uace0\uc778\uc774 \uc7a0\ub4e0 \uc7a5\uc18c\ub97c \ucc3e\ub294 \ud55c \uc7a5\uba74. \ud568\uaed8 \uc7a0\ub4dc\ub294 \uc77c\ub9cc\uc740 \uc5c6\ub3c4\ub85d.","\u3010\uc870\uc791\u3011\ubb34\uc5b8\uac00\ub97c \ub2e4\ub8e8\uba70 \uc18c\uc6d0\uc744 \uc774\ub8e8\ub294 \ud55c \uc7a5\uba74. \uc6b4\uc804\uc774\ub4e0 \ubb34\uc5c7\uc774\ub4e0 \ub534 \uacf3\uc744 \ubcf4\ub294 \uac83\uc740 \uc8fc\uc758\uac00 \ud544\uc694\ud558\ub2e4.","\u3010\uc2dd\uc0ac\u3011\ubb34\uc5b8\uac00\ub97c \uc591\uc2dd\uc73c\ub85c \uc0bc\uc544 \uc790\uc2e0\uc758 \ud798\uc744 \ube44\ucd95\ud558\ub294 \ud55c \uc7a5\uba74. \ud589\ub3d9\ud558\uba74 \uc18c\ubaa8\ub41c\ub2e4. \ubc30\uace0\ud504\uba74 \uc544\ubb34\uac83\ub3c4 \uc548 \ub41c\ub2e4.","\u3010\ud734\uc2dd\u3011\ub098\ub0a0\uc758 \ud2c8\uc0c8, \uc26c\uc5b4 \uac00\ub294 \ud55c \uc7a5\uba74. \'\uc544\ubb34\uac83\ub3c4 \ud558\uc9c0 \uc54a\ub294\ub2e4\'\ub294 \uac83\ub3c4 \ud6cc\ub96d\ud55c \ud589\ub3d9\uc774\ub2e4.","\u3010\ubabd\ud658\u3011\ud604\uc2e4\uc5d0 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \ubb34\uc5b8\uac00\uc5d0 \ube60\uc9c0\ub294 \ud55c \uc7a5\uba74. \uc2dc\uac04\ub300\uc5d0 \uc0c1\uad00\uc5c6\uc774 \uc5b8\uc820\uac00\ub294 \ubc18\ub4dc\uc2dc \uae68\uc5b4\ub0a0 \uac83\uc774\ub2e4."]]]}}}}')}}]);